# ===== main.py =====
import json
from typing import Any, Dict

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse, Response
from pydantic import BaseModel


class Health(BaseModel):
    status: str


app = FastAPI(title="Health and Echo API")


def _invalid(message: str) -> JSONResponse:
    return JSONResponse(status_code=422, content={"detail": message})


def _reject_constant(name: str) -> Any:
    # json.loads accepts NaN/Infinity/-Infinity by default; these are not JSON.
    raise ValueError(f"non-standard JSON constant {name} is not allowed")


@app.get("/health", response_model=Health)
def health() -> Health:
    return Health(status="ok")


@app.post("/echo")
async def echo(request: Request):
    raw = await request.body()
    if not raw.strip():
        return _invalid("Request body is required and must be a JSON object")
    try:
        # Strict UTF-8 decoding: a leading UTF-8 BOM (b'\xef\xbb\xbf') is NOT
        # stripped, so BOM-prefixed bodies are rejected with 422. RFC 8259
        # says senders must not emit a BOM.
        text = raw.decode("utf-8")
        payload = json.loads(text, parse_constant=_reject_constant)
        # Serialize strictly here so values such as 1e400 (parsed to inf)
        # are rejected as 422 instead of failing later during the response.
        encoded = json.dumps(payload, allow_nan=False)
    except RecursionError:
        return _invalid("Malformed JSON body: nesting too deep")
    except (ValueError, UnicodeDecodeError) as exc:
        return _invalid(f"Malformed JSON body: {exc}")
    if not isinstance(payload, dict):
        return _invalid(
            "Request body must be a JSON object, got "
            + type(payload).__name__
        )
    # Valid object: re-serialised from the parsed dict. The echo is therefore
    # not byte-faithful: key order is preserved, but duplicate keys collapse
    # to the last value (e.g. {"a":1,"a":2} echoes as {"a":2}).
    return Response(content=encoded, media_type="application/json")


