def test_echo_flat_object(client):
    body = {"name": "x", "count": 3, "ok": True}
    response = client.post("/echo", json=body)
    assert response.status_code == 200
    assert response.json() == body


def test_echo_large_int_float_and_unicode_unchanged(client):
    body = {"big": 12345678901234567890, "f": 1.5, "s": "é"}
    response = client.post("/echo", json=body)
    assert response.status_code == 200
    assert response.json() == body


def test_echo_unicode_and_big_int_sent_as_raw_bytes(client):
    raw = '{"big": 12345678901234567890, "f": 1.5, "s": "é"}'.encode("utf-8")
    response = client.post("/echo", content=raw, headers=JSON_HEADERS)
    assert response.status_code == 200
    assert response.json() == json.loads(raw)


def test_get_echo_returns_405(client):
    response = client.get("/echo")
    assert response.status_code == 405
    assert response.headers.get("allow") == "POST"


@pytest.mark.parametrize("method", ["put", "delete"])
def test_non_post_methods_on_echo_return_405(client, method):
    response = client.request(method.upper(), "/echo", json={})
    assert response.status_code == 405
    assert response.headers.get("allow") == "POST"


# --- T3: input validation ---

def test_malformed_json_returns_422(client):
    response = client.post("/echo", content=b"{bad", headers=JSON_HEADERS)
    assert_422_with_detail(response)


@pytest.mark.parametrize(
    "raw",
    [b"[1,2]", b'"x"', b"5", b"true", b"null"],
    ids=["list", "string", "number", "boolean", "null"],
)
def test_non_object_json_returns_422(client, raw):
    # Raw bytes so that JSON null is actually sent as the body "null".
    response = client.post("/echo", content=raw, headers=JSON_HEADERS)
    assert_422_with_detail(response)


def test_missing_body_returns_422(client):
    response = client.post("/echo")
    assert_422_with_detail(response)


def test_empty_body_returns_422(client):
    response = client.post("/echo", content=b"", headers=JSON_HEADERS)
    assert_422_with_detail(response)


def test_whitespace_only_body_returns_422(client):
    response = client.post("/echo", content=b"   \n\t ", headers=JSON_HEADERS)
    assert_422_with_detail(response)


@pytest.mark.parametrize(
    "raw",
    [b'{"a": NaN}', b'{"a": Infinity}', b'{"a": -Infinity}'],
    ids=["NaN", "Infinity", "-Infinity"],
)
def test_non_standard_json_constants_return_422(client, raw):
    response = client.post("/echo", content=raw, headers=JSON_HEADERS)
    assert_422_with_detail(response)


def test_deeply_nested_json_returns_422(client):
    response = client.post("/echo", content=b"[" * 100000, headers=JSON_HEADERS)
    assert_422_with_detail(response)


def test_number_overflowing_to_infinity_returns_422(client):
    # 1e400 parses to float('inf'), which is not representable in JSON.
    response = client.post("/echo", content=b'{"a": 1e400}', headers=JSON_HEADERS)
    assert_422_with_detail(response)


def test_utf8_bom_prefixed_body_returns_422(client):
