import json

import pytest
from fastapi.testclient import TestClient

from main import app

JSON_HEADERS = {"content-type": "application/json"}


@pytest.fixture
def client():
    with TestClient(app) as c:
        yield c


def assert_422_with_detail(response):
    assert response.status_code == 422
    body = response.json()
    assert "detail" in body


# --- Criterion 1: malformed JSON returns 422 with 'detail' ---

@pytest.mark.parametrize(
    "raw",
    [b"{bad", b'{"a": 1', b"{'a': 1}", b"not json"],
    ids=["truncated_brace", "unclosed_object", "single_quotes", "bare_words"],
)
def test_malformed_json_returns_422_with_detail(client, raw):
    response = client.post("/echo", content=raw, headers=JSON_HEADERS)
    assert_422_with_detail(response)


# --- Criterion 2: non-object valid JSON returns 422 with 'detail' ---

@pytest.mark.parametrize(
    "raw",
    [b"[1,2]", b'"x"', b"5", b"true", b"null"],
    ids=["list", "string", "number", "boolean", "null"],
)
def test_non_object_json_returns_422_with_detail(client, raw):
    response = client.post("/echo", content=raw, headers=JSON_HEADERS)
    assert_422_with_detail(response)


# --- Criterion 3: empty / missing body returns 422 with 'detail' ---

def test_missing_body_returns_422_with_detail(client):
    response = client.post("/echo")
    assert_422_with_detail(response)


def test_empty_body_returns_422_with_detail(client):
    response = client.post("/echo", content=b"", headers=JSON_HEADERS)
    assert_422_with_detail(response)


def test_whitespace_only_body_returns_422_with_detail(client):
    response = client.post("/echo", content=b"   \n\t ", headers=JSON_HEADERS)
    assert_422_with_detail(response)


# --- Criterion 4: valid object bodies still echo with 200 ---

@pytest.mark.parametrize(
    "body",
    [{}, {"a": 1, "b": [1, 2], "c": {"d": None}}, {"nested": {"x": [True]}}, {"s": "é", "f": 1.5}],
    ids=["empty", "nested", "deep_nested", "unicode_float"],
)
def test_valid_object_bodies_echo_200(client, body):
    response = client.post("/echo", json=body)
    assert response.status_code == 200
    assert response.json() == body


def test_valid_object_raw_bytes_echo_200(client):
    raw = json.dumps({"a": 1, "b": "x"}).encode("utf-8")
    response = client.post("/echo", content=raw, headers=JSON_HEADERS)
    assert response.status_code == 200
    assert response.json() == {"a": 1, "b": "x"}


# --- Criterion 5: the suite itself is run with pytest (this module's tests pass) ---

def test_suite_sanity_health_endpoint_ok(client):
    response = client.get("/health")
    assert response.status_code == 200
    assert response.json() == {"status": "ok"}
